        due_at=due_at,
        tags=tags or [],
        created_at=created_at or NOW - timedelta(hours=id),
    )


@pytest.fixture()
def tasks():
    return [
        _task(1, "Alpha", priority=TaskPriority.HIGH, tags=[Tag("work")]),
        _task(2, "Beta", status=TaskStatus.DONE, tags=[Tag("home")]),
        _task(3, "Gamma", due_at=NOW - timedelta(days=1), tags=[Tag("work"), Tag("urgent")]),
        _task(4, "Delta", due_at=NOW + timedelta(days=1)),
        _task(5, "Epsilon", priority=TaskPriority.LOW),
    ]


class TestTaskQueryValidation:
    def test_invalid_sort_field(self):
        with pytest.raises(TaskQueryError, match="sort must be"):
            TaskQuery(sort="invalid")

    def test_limit_zero(self):
        with pytest.raises(TaskQueryError, match="limit must be"):
            TaskQuery(limit=0)

    def test_limit_too_large(self):
        with pytest.raises(TaskQueryError, match="limit must be"):
