    def test_negative_offset(self):
        with pytest.raises(TaskQueryError, match="offset must be"):
            TaskQuery(offset=-1)

    def test_invalid_tag(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_whitespace_search_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_tag_normalized(self):
        q = TaskQuery(tag="  Work  ")
        assert q.tag == "work"


class TestFilterByStatus:
    def test_pending_only(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING), NOW)
        assert all(t.status == TaskStatus.PENDING for t in page.items)
        assert page.total == 4

    def test_done_only(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].id == 2


