class TestSorting:
    def test_sort_by_created_at_asc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        created = [t.created_at for t in page.items]
        assert created == sorted(created)

    def test_sort_by_created_at_desc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at", descending=True), NOW)
        created = [t.created_at for t in page.items]
        assert created == sorted(created, reverse=True)

    def test_sort_by_priority(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        priorities = [TaskPriority.order_key(t.priority) for t in page.items]
        assert priorities == sorted(priorities)

    def test_sort_by_title(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        titles = [t.title.lower() for t in page.items]
        assert titles == sorted(titles)

    def test_sort_by_due_at(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        # Tasks without due_at should be last
        due_present = [t for t in page.items if t.due_at is not None]
        due_absent = [t for t in page.items if t.due_at is None]
        assert all(t.due_at is None for t in due_absent)
        # due_present should be sorted ascending
        dates = [t.due_at for t in due_present]
        assert dates == sorted(dates)


class TestPagination:
    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2), NOW)
        assert len(page.items) == 2
        assert page.total == 5
        assert page.has_more is True

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2, offset=4), NOW)
        assert len(page.items) == 1
        assert page.has_more is False

    def test_offset_beyond(self, tasks):
        page = apply_query(tasks, TaskQuery(offset=100), NOW)
        assert page.items == []
        assert page.total == 5
        assert page.has_more is False

    def test_has_more_boundary(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=5), NOW)
        assert page.has_more is False


class TestCombinedFilters:
    def test_status_and_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING, tag="work"), NOW)
        assert page.total == 2

    def test_search_and_overdue(self, tasks):
        page = apply_query(tasks, TaskQuery(search="gam", overdue=True), NOW)
        assert page.total == 1
        assert page.items[0].id == 3

"""Tests for tasks_api.repository — InMemoryTaskRepository and normalize_tags."""

from __future__ import annotations

from datetime import datetime, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags

NOW = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)


def _make_task(id=1, title="test"):
    return Task(id=id, title=title, created_at=NOW)


class TestInMemoryTaskRepository:
    def test_add_and_get(self, memory_repo):
        t = _make_task()
        memory_repo.add(t)
        assert memory_repo.get(1) is t

    def test_get_missing(self, memory_repo):
        assert memory_repo.get(99) is None

    def test_add_duplicate_raises(self, memory_repo):
        memory_repo.add(_make_task())
        with pytest.raises(ValueError, match="already exists"):
            memory_repo.add(_make_task())

    def test_list_returns_all(self, memory_repo):
        memory_repo.add(_make_task(1))
        memory_repo.add(_make_task(2, "other"))
        items = list(memory_repo.list())
        assert len(items) == 2

    def test_update_existing(self, memory_repo):
        t = _make_task()
        memory_repo.add(t)
        t.title = "updated"
        memory_repo.update(t)
        assert memory_repo.get(1).title == "updated"

    def test_update_missing_raises(self, memory_repo):
        with pytest.raises(KeyError):
            memory_repo.update(_make_task(99))

    def test_delete_existing(self, memory_repo):
        memory_repo.add(_make_task())
        assert memory_repo.delete(1) is True
        assert memory_repo.get(1) is None

    def test_delete_missing(self, memory_repo):
        assert memory_repo.delete(99) is False

    def test_next_id_increments(self, memory_repo):
        assert memory_repo.next_id() == 1
        assert memory_repo.next_id() == 2
        assert memory_repo.next_id() == 3


class TestNormalizeTags:
    def test_deduplicates(self):
        result = normalize_tags([Tag("a"), Tag("A"), Tag("b")])
        assert [t.name for t in result] == ["a", "b"]

    def test_converts_strings(self):
        result = normalize_tags(["Hello", "world"])
        assert [t.name for t in result] == ["hello", "world"]

    def test_preserves_order(self):
        result = normalize_tags(["b", "a", "c"])
        assert [t.name for t in result] == ["b", "a", "c"]

    def test_empty(self):
        assert normalize_tags([]) == []

    def test_mixed_tag_and_string(self):
        result = normalize_tags([Tag("x"), "y"])
        assert [t.name for t in result] == ["x", "y"]
